def merge_slots(slots: list[list[int]]) -> list[list[int]]:
    if not slots:
        return []
    sorted_slots = sorted(slots)
    merged = [sorted_slots[0][:]]
    for start, end in sorted_slots[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged
```

