def tally_votes(votes: list[str]) -> list[str]:
    counts = {}
    first_seen = {}
    for index, candidate in enumerate(votes):
        counts[candidate] = counts.get(candidate, 0) + 1
        first_seen.setdefault(candidate, index)
    return sorted(counts, key=lambda candidate: (-counts[candidate], first_seen[candidate]))
```

