def grid_islands(grid: list[str]) -> list[int]:
    if not grid:
        return []
    rows, cols = len(grid), len(grid[0])
    visited = set()
    areas = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != "#" or (r, c) in visited:
                continue
            stack = [(r, c)]
            visited.add((r, c))
            area = 0
            while stack:
                cr, cc = stack.pop()
                area += 1
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == "#" and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        stack.append((nr, nc))
            areas.append(area)
    return sorted(areas, reverse=True)
```

