def bracket_depth(s: str) -> int:
    opening = "([{"
    closing = ")]}"
    pairs = dict(zip(closing, opening))
    stack = []
    max_depth = 0
    for char in s:
        if char in opening:
            stack.append(char)
            max_depth = max(max_depth, len(stack))
        elif char in closing:
            if not stack or stack.pop() != pairs[char]:
                return -1
    return max_depth if not stack else -1
